const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');

const VOID = new Set(['br', 'hr', 'img', 'input', 'meta', 'link', 'source', 'path', 'circle', 'line', 'rect', 'stop', 'use', 'area', 'col']);

let fail = 0;

// ---------- 1. tag balance ----------
const stack = [];
const tagRe = /<(\/?)([a-zA-Z][a-zA-Z0-9-]*)((?:"[^"]*"|'[^']*'|[^>"'])*?)(\/?)>/g;
let m;
while ((m = tagRe.exec(html)) !== null) {
  const closing = m[1] === '/';
  const name = m[2].toLowerCase();
  const selfClose = m[4] === '/';
  if (VOID.has(name) || selfClose) continue;
  if (!closing) {
    stack.push({ name, index: m.index });
  } else {
    const top = stack.pop();
    if (!top || top.name !== name) {
      console.log('  MISMATCH: </' + name + '> at offset ' + m.index + ' but open was <' + (top ? top.name : 'NOTHING') + '>');
      fail++;
    }
  }
}
if (stack.length) { console.log('  UNCLOSED:', stack.map(s => '<' + s.name + '>').join(', ')); fail++; }
console.log(fail === 0 ? '[ok] tag balance: all elements closed and correctly nested' : '[FAIL] tag balance');

// ---------- 2. inline JS syntax ----------
[...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].forEach((s, i) => {
  try { new Function(s[1]); console.log('[ok] script[' + i + '] parses'); }
  catch (e) { console.log('[FAIL] script[' + i + ']: ' + e.message); fail++; }
});

// ---------- 3. no hardcoded colors outside the token block ----------
const style = html.match(/<style>([\s\S]*?)<\/style>/)[1];
const tokenEnd = style.indexOf('   2. 基础');
const rules = style.slice(tokenEnd);
const stray = [...rules.matchAll(/#[0-9a-fA-F]{3,8}\b|rgba?\([^)]*\)|\b(?:white|black|red|blue|green|gray|grey)\b/g)].map(x => x[0]);
console.log(stray.length === 0 ? '[ok] no raw color values outside the semantic token blocks' : '[FAIL] stray colors: ' + stray.join(', '));
if (stray.length) fail++;

// ---------- 4. every var() reference resolves to a declared token ----------
const declaredIn = (block) => new Set([...block.matchAll(/(--[a-z0-9-]+)\s*:/g)].map(x => x[1]));
const allDeclared = new Set();
for (const block of style.split('}')) for (const d of declaredIn(block)) allDeclared.add(d);
const used = new Set([...style.matchAll(/var\((--[a-z0-9-]+)/g)].map(x => x[1]));
const missing = [...used].filter(u => !allDeclared.has(u));
console.log(missing.length === 0 ? '[ok] all ' + used.size + ' var() references resolve' : '[FAIL] undeclared: ' + missing.join(', '));
if (missing.length) fail++;

// ---------- 5. required structure ----------
const need = [
  ['nav landmark', /<nav[^>]+aria-label="主导航"/],
  ['hero', /class="hero"/],
  ['3 feature cards', null],
  ['pricing tiers', null],
  ['subscribe form', /id="subscribe-form"/],
  ['footer', /<footer/],
  ['theme toggle', /id="theme-toggle"/],
  ['skip link', /class="skip-link"/],
  ['reduced-motion', /@media \(prefers-reduced-motion: reduce\)/],
  ['system theme follow', /@media \(prefers-color-scheme: light\)/],
  ['viewport meta', /name="viewport"/],
  ['lang zh-CN', /<html lang="zh-CN">/],
];
console.log('[--] structure:');
for (const [label, re] of need) {
  if (re === null) continue;
  console.log((re.test(html) ? '  [ok] ' : '  [FAIL] ') + label);
  if (!re.test(html)) fail++;
}
const cards = (html.match(/class="card"/g) || []).length;
const plans = (html.match(/class="plan[" ]/g) || []).length;
console.log((cards === 3 ? '  [ok] ' : '  [FAIL] ') + 'feature cards = ' + cards);
console.log((plans === 3 ? '  [ok] ' : '  [FAIL] ') + 'pricing tiers = ' + plans);
if (cards !== 3 || plans !== 3) fail++;

// ---------- 6. no emoji anywhere ----------
const emoji = html.match(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{1F000}-\u{1F2FF}]/gu);
console.log(emoji ? '[FAIL] emoji found: ' + emoji.join(' ') : '[ok] zero emoji (icons are inline SVG only)');
if (emoji) fail++;

// ---------- 7. body typography ----------
const base = /font-size: 16px;[\s\S]{0,80}?line-height: 1\.5;/.test(style);
console.log(base ? '[ok] body is 16px / line-height 1.5' : '[FAIL] body typography');
if (!base) fail++;

// ---------- 8. accessible error wiring ----------
const wired = ['email', 'city', 'consent'].every(n => html.includes('id="' + n + '-error"'));
const alerts = (html.match(/role="alert"/g) || []).length;
console.log(wired && alerts === 3 ? '[ok] 3 fields wired to role="alert" inline error slots' : '[FAIL] error wiring (alerts=' + alerts + ')');
if (!wired || alerts !== 3) fail++;

// ---------- 9. contrast ----------
function lum(hex) {
  const c = hex.replace('#', '');
  const [r, g, b] = [0, 2, 4].map(i => parseInt(c.slice(i, i + 2), 16) / 255)
    .map(v => (v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
const ratio = (a, b) => { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };
const themes = {
  dark: { bg: '#0b1020', surface: '#121a30', fieldBg: '#0c1222', text: '#eef2ff', muted: '#aab6d8', accent: '#5eead4', accentInk: '#04231d', danger: '#ffa8a8', focus: '#8ab4ff', border: '#5b6d9c' },
  light: { bg: '#f5f7fc', surface: '#ffffff', fieldBg: '#f7f9fd', text: '#101728', muted: '#4a5470', accent: '#0f766e', accentInk: '#ffffff', danger: '#b3261e', focus: '#0b5fff', border: '#7d8cb0' },
};
console.log('[--] contrast:');
for (const [name, t] of Object.entries(themes)) {
  const checks = [
    ['body text on bg', t.text, t.bg, 4.5],
    ['body text on surface', t.text, t.surface, 4.5],
    ['muted text on bg', t.muted, t.bg, 4.5],
    ['muted text on surface', t.muted, t.surface, 4.5],
    ['muted text on field', t.muted, t.fieldBg, 4.5],
    ['link/accent text on bg', t.accent, t.bg, 4.5],
    ['accent text on surface', t.accent, t.surface, 4.5],
    ['button label on accent', t.accentInk, t.accent, 4.5],
    ['error text on surface', t.danger, t.surface, 4.5],
    ['focus ring vs bg', t.focus, t.bg, 3],
    ['focus ring vs surface', t.focus, t.surface, 3],
    ['control border vs field', t.border, t.fieldBg, 3],
    ['control border vs surface', t.border, t.surface, 3],
  ];
  for (const [label, fg, bg, min] of checks) {
    const r = ratio(fg, bg);
    const ok = r >= min;
    if (!ok) fail++;
    console.log('  ' + (ok ? '[ok] ' : '[FAIL] ') + name + ' — ' + label + ': ' + r.toFixed(2) + ':1 (need ' + min + ')');
  }
}

console.log('\n' + (fail === 0 ? '=== ALL CHECKS PASSED ===' : '=== ' + fail + ' CHECK(S) FAILED ==='));

