// Builds _test.html: index.html + an instrumentation script that records
// console errors, layout overflow and touch-target sizes into the DOM.
const fs = require('fs');
let html = fs.readFileSync('index.html', 'utf8');

const collector = `<script>
window.__errors = [];
window.addEventListener('error', function (e) {
  window.__errors.push('error: ' + (e.message || '') + ' @' + (e.filename || '') + ':' + (e.lineno || ''));
});
window.addEventListener('unhandledrejection', function (e) {
  window.__errors.push('unhandledrejection: ' + e.reason);
});
['error', 'warn'].forEach(function (level) {
  var orig = console[level];
  console[level] = function () {
    window.__errors.push('console.' + level + ': ' + Array.prototype.join.call(arguments, ' '));
    return orig.apply(console, arguments);
  };
});
<\/script>`;

const probe = `<script>
function rect(el) { var r = el.getBoundingClientRect(); return { l: r.left, r: r.right, w: r.width, h: r.height }; }
function name(el) {
  var n = el.tagName.toLowerCase();
  if (el.id) n += '#' + el.id;
  if (typeof el.className === 'string' && el.className.trim()) n += '.' + el.className.trim().split(/\\s+/).join('.');
  return n;
}
window.addEventListener('load', function () {
  setTimeout(function () {
    var out = {};
    var de = document.documentElement;
    out.viewport = window.innerWidth + 'x' + window.innerHeight;
    out.docScrollWidth = de.scrollWidth;
    out.clientWidth = de.clientWidth;
    out.horizontalOverflow = de.scrollWidth > de.clientWidth + 0.5;
    out.scheme = getComputedStyle(document.body).colorScheme;
    out.dataTheme = de.getAttribute('data-theme') || '(none -> follows system)';

    // any element crossing the viewport horizontally
    var over = [];
    document.querySelectorAll('body *').forEach(function (el) {
      var r = rect(el);
      if (r.w === 0 && r.h === 0) return;
      if (r.r > window.innerWidth + 0.5 || r.l < -0.5) over.push(name(el) + ' [' + Math.round(r.l) + '..' + Math.round(r.r) + ']');
    });
    out.overflowing = over.slice(0, 20);

    // touch targets >= 44x44
    var small = [];
    document.querySelectorAll('a[href], button, input, select, [tabindex]').forEach(function (el) {
      var r = rect(el);
      if (r.w === 0 || r.h === 0) return;
      if (r.h < 44 || r.w < 44) small.push(name(el) + ' ' + Math.round(r.w) + 'x' + Math.round(r.h));
    });
    out.smallTargets = small;

    // tab order reachability
    var focusables = [].slice.call(document.querySelectorAll('a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'))
      .filter(function (el) { return el.offsetParent !== null || el === document.activeElement; });
    out.focusableCount = focusables.length;
    out.focusableOrder = focusables.map(name);

    var cs = getComputedStyle(document.body);
    out.bodyType = cs.fontSize + ' / line-height ' + cs.lineHeight;

    // hero route svg actually rendered with a size
    var svg = document.querySelector('.route-card');
    if (svg) out.routeCard = Math.round(rect(svg).w) + 'x' + Math.round(rect(svg).h);

    // clickable area of the consent row
    var lab = document.querySelector('.field--check label');
    if (lab) out.consentLabel = Math.round(rect(lab).w) + 'x' + Math.round(rect(lab).h);

    out.consoleErrors = window.__errors;
    var pre = document.createElement('pre');
    pre.id = '__report';
    pre.textContent = '@@REPORT@@' + JSON.stringify(out) + '@@END@@';
    document.body.appendChild(pre);
  }, 400);
});
<\/script>`;

html = html.replace('<head>', '<head>\n' + collector);
html = html.replace('</body>', probe + '\n</body>');
