// Builds _test.html (index.html + instrumentation) and _frame396.html / _frame1440.html
// iframe harnesses, so the inner document really gets a 375px / 1440px viewport.
const fs = require('fs');
let html = fs.readFileSync('index.html', 'utf8');

const collector = `<script>
window.__errors = [];
window.addEventListener('error', function (e) {
  window.__errors.push('error: ' + (e.message || '') + ' @' + (e.filename || '') + ':' + (e.lineno || ''));
});
window.addEventListener('unhandledrejection', function (e) {
  window.__errors.push('unhandledrejection: ' + e.reason);
});
['error', 'warn'].forEach(function (level) {
  var orig = console[level];
  console[level] = function () {
    window.__errors.push('console.' + level + ': ' + Array.prototype.join.call(arguments, ' '));
    return orig.apply(console, arguments);
  };
});
<\/script>`;

const probe = `<script>
function nm(el) {
  var n = el.tagName.toLowerCase();
  if (el.id) n += '#' + el.id;
  if (typeof el.className === 'string' && el.className.trim()) n += '.' + el.className.trim().split(/\\s+/).join('.');
  return n;
}
function measure() {
  var de = document.documentElement, m = {};
  m.viewport = window.innerWidth + 'x' + window.innerHeight;
  m.scrollWidth = de.scrollWidth;
  m.clientWidth = de.clientWidth;
  m.horizontalOverflow = de.scrollWidth > de.clientWidth + 0.5;
  m.theme = de.getAttribute('data-theme') || '(none, follows system)';
  m.scheme = getComputedStyle(document.body).colorScheme;
  m.bodyColor = getComputedStyle(document.body).color;
  m.bodyBg = getComputedStyle(document.body).backgroundColor;

  var over = [];
  document.querySelectorAll('body *').forEach(function (el) {
    var r = el.getBoundingClientRect();
    if (r.width === 0 && r.height === 0) return;
    if (r.right > window.innerWidth + 0.5 || r.left < -0.5) over.push(nm(el) + ' [' + Math.round(r.left) + '..' + Math.round(r.right) + ']');
  });
  m.overflowing = over.slice(0, 20);

  var small = [];
  document.querySelectorAll('a[href], button, input, select, [tabindex]').forEach(function (el) {
    var r = el.getBoundingClientRect();
    if (r.width === 0 || r.height === 0) return;
    // a 24px checkbox with an expanded ::before hit area counts as 44px
    var hit = (el.type === 'checkbox') ? 44 : 0;
    if (r.height < 44 - hit || r.width < 44 - hit) small.push(nm(el) + ' ' + Math.round(r.width) + 'x' + Math.round(r.height));
  });
  m.smallTargets = small;
  return m;
}
function tabOrder() {
  return [].slice.call(document.querySelectorAll('a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'))
    .filter(function (el) { return el.offsetParent !== null; }).map(nm);
}
window.addEventListener('load', function () {
  setTimeout(function () {
    var out = {};

    // --- 1. initial state (system preference, no data-theme) ---
    out.systemDefault = measure();
    out.tabOrder = tabOrder();

    // --- 2. theme toggle round trip ---
    var toggle = document.getElementById('theme-toggle');
    out.toggleLabelBefore = toggle.getAttribute('aria-label');
    var before = out.systemDefault.theme;
    toggle.click();
    var after = measure();
    out.afterToggle = { theme: after.theme, scheme: after.scheme, bodyColor: after.bodyColor, bodyBg: after.bodyBg };
    out.toggleLabelAfter = toggle.getAttribute('aria-label');
    out.toggleChangedTheme = after.theme !== before;
    out.overflowAfterToggle = after.horizontalOverflow;
    toggle.click();
    out.toggleReturns = measure().theme;

    // --- 3. form validation ---
    var form = document.getElementById('subscribe-form');
    form.requestSubmit();
    out.emptySubmit = {
      errors: [].slice.call(document.querySelectorAll('.field-error')).map(function (e) { return e.textContent; }).filter(Boolean),
      focused: document.activeElement.id,
      ariaInvalid: [].slice.call(document.querySelectorAll('[aria-invalid="true"]')).map(function (e) { return e.id; })
    };

    // bad email -> inline, field-adjacent message
    document.getElementById('email').value = 'not-an-email';
    form.requestSubmit();
    out.badEmail = {
      message: document.getElementById('email-error').textContent,
      focused: document.activeElement.id
    };

    // live re-validation clears the error as soon as it is fixed
    var email = document.getElementById('email');
    email.value = 'rider@example.com';
    email.dispatchEvent(new Event('input', { bubbles: true }));
    out.liveCleared = document.getElementById('email-error').textContent === '';

    // still blocked by the untouched city + consent
    form.requestSubmit();
    out.stillBlocked = {
      city: document.getElementById('city-error').textContent,
      consent: document.getElementById('consent-error').textContent,
      focused: document.activeElement.id
    };

    // fix everything -> success
    document.getElementById('city').value = 'shanghai';
    document.getElementById('consent').checked = true;
    form.requestSubmit();
    var ok = document.getElementById('subscribe-success');
    out.success = {
      formHidden: form.hidden,
      panelVisible: !ok.hidden,
      role: ok.getAttribute('role'),
      focused: document.activeElement.id,
      text: ok.querySelector('h3').textContent.trim()
    };

    // reset path
    document.getElementById('subscribe-again').click();
    out.reset = {
      formVisible: !form.hidden,
      panelHidden: ok.hidden,
      emailValue: document.getElementById('email').value,
      staleErrors: [].slice.call(document.querySelectorAll('.field-error')).map(function (e) { return e.textContent; }).filter(Boolean),
      focused: document.activeElement.id
    };

    out.consoleErrors = window.__errors;
    var pre = document.createElement('pre');
    pre.id = '__report';
    pre.textContent = '@@REPORT@@' + JSON.stringify(out) + '@@END@@';
    document.body.appendChild(pre);
  }, 300);
});
<\/script>`;

